={
  "query": "query LabelBridgeEtiquetaActual($id: ID!, $namespace: String!, $key: String!) { order(id: $id) { id name metafield(namespace: $namespace, key: $key) { id value } } }",
  "variables": { "id": "{{ $json.order_gid }}", "namespace": "{{ $json.metafield_namespace }}", "key": "{{ $json.metafield_key }}" }
}

parameters.jsCode:
// Si el pedido ya tiene la URL de la etiqueta en el metafield (por ejemplo,
// porque Shopify reenvió el webhook), NO se crea otra etiqueta en la paquetería.
// Si no la tiene, se devuelve el pedido completo para el nodo de la paquetería.

const pedido = $('Configuración').first().json;
const res = $input.first().json;

if (Array.isArray(res.errors) && res.errors.length) {
  throw new Error('Shopify GraphQL (consultar metafield): ' + JSON.stringify(res.errors));
}
if (!res.data?.order) {
  throw new Error(`No se pudo leer el pedido ${pedido.order_gid}. Revisa la credencial, el subdominio en "Configuración" y el scope read_orders.`);
}
if (res.data.order.metafield?.value) {
  return [];   // ya tiene etiqueta: no hacemos nada
}

return [{ json: pedido }];

// Busca la URL de la etiqueta en la respuesta de tu paquetería.
// Por defecto espera { "label_url": "https://..." }. Si tu API la devuelve en
// otro campo, añádelo al principio de CAMPOS (admite rutas con puntos).
const CAMPOS = [
  'label_url',                 // genérico (también Shippo)
  'labelUrl',
  'label.url',
  'data.label_url',
  'postage_label.label_url',   // EasyPost
  'label_download.pdf',        // ShipEngine
  'label_download.href',
];

const pedido = $('Configuración').first().json;
const respuesta = $input.first().json;

const leer = (obj, ruta) => ruta.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
let labelUrl = '';
for (const campo of CAMPOS) {
  const valor = leer(respuesta, campo);
  if (typeof valor === 'string' && valor.trim()) {
    labelUrl = valor.trim();
    break;
  }
}

if (!labelUrl) {
  throw new Error(
    'No se encontró la URL de la etiqueta en la respuesta de la paquetería. ' +
    '¿Editaste y ACTIVASTE el nodo "Crear etiqueta en tu paquetería (EDITAR)"? ' +
    'Si tu API usa otro campo, añádelo a CAMPOS en este nodo.'
  );
}
if (!/^https?:\/\//i.test(labelUrl)) {
  throw new Error(`La URL de la etiqueta debe empezar por http(s):// y se recibió: ${labelUrl}`);
}

return [{
  json: {
    order_gid: pedido.order_gid,
    order_name: pedido.name,
    metafield_namespace: pedido.metafield_namespace,
    metafield_key: pedido.metafield_key,
    label_url: labelUrl,
  },
}];

