={
  "query": "mutation LabelBridgeGuardarEtiqueta($metafields: [MetafieldsSetInput!]!) { metafieldsSet(metafields: $metafields) { metafields { id key namespace } userErrors { field message code } } }",
  "variables": {
    "metafields": [
      {
        "ownerId": "{{ $json.order_gid }}",
        "namespace": "{{ $json.metafield_namespace }}",
        "key": "{{ $json.metafield_key }}",
        "type": "url",
        "value": {{ JSON.stringify($json.label_url) }}
      }
    ]
  }
}

parameters.jsCode:
// Falla de forma visible si Shopify no guardó el metafield (errors / userErrors).
const datos = $('Extraer URL de la etiqueta').first().json;
const res = $input.first().json;

if (Array.isArray(res.errors) && res.errors.length) {
  throw new Error('Shopify GraphQL (metafieldsSet): ' + JSON.stringify(res.errors));
}

const userErrors = res.data?.metafieldsSet?.userErrors ?? [];
if (userErrors.length) {
  const detalle = userErrors.map((e) => `${e.code ?? ''} ${e.message}`.trim()).join(' | ');
  throw new Error(`Shopify no guardó la etiqueta en el pedido ${datos.order_name}: ${detalle}`);
}

const metafield = res.data?.metafieldsSet?.metafields?.[0];
return [{
  json: {
    ok: true,
    order_name: datos.order_name,
    label_url: datos.label_url,
    metafield_id: metafield?.id ?? null,
  },
}];
